import type { TableName, Record } from '../db'

type TriggerConditions<T extends TableName> = {
    /**
     * Type of notification generation: engine (record insert/update), event (system event), or triggered (manual)
     * @default 'engine'
     */
    generationType?: 'engine' | 'event' | 'triggered'
    /** Whether to send notification when a record is inserted */
    onRecordInsert?: boolean
    /** Whether to send notification when a record is updated */
    onRecordUpdate?: boolean
    /** Name of the event that triggers this notification (for event-based notifications) */
    eventName?: string
    /**
     * The execution order of the notification (lower numbers execute first)
     * @default 0
     */
    weight?: number
    /** Script-based condition that must be met for the notification to send */
    condition?: string
    /** Advanced condition script for complex notification logic */
    advancedCondition?: string
    /** The table that the notification item refers to */
    itemTable?: T
    /** Which event parameter contains the affected field (parm1 or parm2) */
    affectedFieldOnEvent?: 'parm1' | 'parm2'
    /**
     * The item to use for the notification context
     * @default 'event.parm1'
     */
    item?: string
    /** The execution order of the notification */
    order?: number
}

type RecipientDetails = {
    /** List of users who will receive the notification */
    recipientUsers?: (string | Record<'sys_user'>)[]
    /** Fields on the record that contain recipient user references */
    recipientFields?: string[]
    /** List of groups whose members will receive the notification */
    recipientGroups?: (string | Record<'sys_user_group'>)[]
    /**
     * Whether to exclude delegates from receiving the notification
     * @default false
     */
    excludeDelegates?: boolean
    /**
     * Whether all users can subscribe to this notification
     * @default false
     */
    isSubscribableByAllUsers?: boolean
    /**
     * Whether to send the notification to the record creator
     * @default true
     */
    sendToCreator?: boolean
    /** Whether event parameter 1 contains a recipient */
    eventParm1WithRecipient?: boolean
    /** Whether event parameter 2 contains a recipient */
    eventParm2WithRecipient?: boolean
}

type EmailContent = {
    /**
     * MIME content type for the email
     * @default 'text/html'
     */
    contentType?: 'text/html' | 'multipart/mixed' | 'text/plain'
    /** Email template to use for formatting the notification */
    template?: string | Record<'sysevent_email_template'>
    /** Email style to apply to the notification */
    style?: string | Record<'sys_email_style'>
    /** Subject line of the email */
    subject?: string
    /** Message content (legacy field) */
    message?: string
    /** HTML version of the message content */
    messageHtml?: string
    /** Plain text version of the message content */
    messageText?: string
    /** SMS alternate message for mobile notifications */
    smsAlternate?: string
    /** Priority/importance level of the email */
    importance?: 'low' | 'high'
    /** Whether to include record attachments in the email */
    includeAttachments?: boolean
    /**
     * Whether to omit the ServiceNow watermark from the email
     * @default false
     */
    omitWatermark?: boolean
    /** Email address to use as the sender */
    from?: string
    /** Email address for replies */
    replyTo?: string
    /**
     * Whether to send only as a push notification (no email)
     * @default false
     */
    pushMessageOnly?: boolean
    /** List of push notification messages to send */
    pushMessageList?: (string | Record<'sys_push_notif_msg'>)[]
    /**
     * Whether to force delivery even if user preferences would block it
     * @default false
     */
    forceDelivery?: boolean
}

type Digest = {
    /**
     * Whether to allow users to receive this notification as a digest
     * @default false
     */
    allow?: boolean
    /**
     * Whether digest mode is enabled by default for this notification
     * @default false
     */
    default?: boolean
    /** Default time interval for digest delivery */
    defaultInterval?: string | Record<'sys_email_digest_interval'>
    /**
     * Type of digest: single (one notification per digest) or multiple (combine multiple notifications)
     * @default 'single'
     */
    type?: 'single' | 'multiple'
    /** Email template to use for digest emails */
    template?: string | Record<'sysevent_email_template'>
    /** Subject line for digest emails */
    subject?: string
    /** HTML content for digest emails */
    html?: string
    /** Plain text content for digest emails */
    text?: string
    /**
     * HTML separator between notifications in a digest
     * @default '<br><hr><br>'
     */
    separatorHtml?: string
    /**
     * Text separator between notifications in a digest
     * @default '\n--------------------------------------------------------------------------------\n'
     */
    separatorText?: string
    /** Email address to use as the sender for digest emails */
    from?: string
    /** Email address for replies to digest emails */
    replyTo?: string
}

export type EmailNotification<T extends TableName> = Now.Internal.WithID<{
    /** Name of the email notification */
    name?: string
    /** Description of the email notification */
    description?: string
    /** The table that this notification applies to (required) */
    table: T
    /**
     * Category for organizing and managing notifications
     * @default 'c97d83137f4432005f58108c3ffa917a' (Default email category)
     */
    category?: string | Record<'sys_notification_category'>
    /**
     * Whether the notification is active and will be sent
     * @default true
     */
    active?: boolean
    /**
     * Whether the notification is mandatory and cannot be unsubscribed from
     * @default false
     */
    mandatory?: boolean
    /**
     * Type of notification: email or calendar invite (vcalendar)
     * @default 'email'
     */
    notificationType?: 'email' | 'vcalendar'
    /** Conditions that determine when the notification is triggered */
    triggerConditions?: TriggerConditions<T>
    /** Configuration for who receives the notification */
    recipientDetails?: RecipientDetails
    /** Email content and formatting options */
    emailContent?: EmailContent
    /** Digest configuration for batching multiple notifications */
    digest?: Digest
    /**
     * Whether to enable dynamic translation of notification content
     * @default false
     */
    enableDynamicTranslation?: boolean
}>

/**
 * Creates an email notification configuration for ServiceNow. Email notifications are automated messages
 * sent to users when specific conditions are met, such as record updates, insertions, or system events.
 *
 * This API allows you to define notifications with trigger conditions, recipient targeting, email content,
 * and digest options. Notifications can be triggered by database operations (insert/update), system events,
 * or manual execution.
 *
 * @param config - Email notification configuration object
 */
export function EmailNotification<T extends TableName>(config: EmailNotification<T>) {
    return config
}
